function renderFilterDialog() {
    const wb = routeWb();
    const sheet = activeSheet(wb);
    const filter = sheetFilters(sheet).find((f) => f.id === filterDlg.filterId);
    if (!filter) { ARC.closeDialog(); return; }
    const eng = makeEngine(sheet);
    const header = eng.display(filter.range.r1, filterDlg.col);
    const name = 'Filter ' + header;
    if (filterDlg.mode === 'values') {
      const boxes = filterDlg.values.map((v) => `<label class="check"><input type="checkbox" name="v" value="${esc(v)}"${filterDlg.checked.indexOf(v) >= 0 ? ' checked' : ''}> ${esc(v)}</label>`).join('');
      ARC.openDialog(`<form data-action="filter-apply-values">
  <div class="filter-values">${boxes}</div>
  <div class="dlg-actions"><button type="button" data-action="filter-clear-selection">Clear selection</button> <button type="submit">Apply</button></div>
  <div class="cond-options">
    <button type="button" data-action="filter-mode" data-id="contains">Text contains</button>
    <button type="button" data-action="filter-mode" data-id="gt">Greater than</button>
    <button type="button" data-action="filter-mode" data-id="before">Before</button>
    <button type="button" data-action="filter-mode" data-id="empty">Is empty</button>
    <button type="button" data-action="filter-mode" data-id="notEmpty">Is not empty</button>
  </div>
</form>`, { title: name });
      return;
    }
    const labels = { contains: 'Text contains', gt: 'Greater than', before: 'Before', empty: 'Is empty', notEmpty: 'Is not empty' };
    const current = labels[filterDlg.op] || 'Text contains';
    ARC.openDialog(`<form data-action="filter-apply-condition">
  ${ARC.combobox({ label: 'Condition', name: 'condition', options: ['Text contains', 'Greater than', 'Before', 'Is empty', 'Is not empty'], value: current })}
  <label for="filter-value">Value</label>
  <input id="filter-value" name="value" type="text" placeholder="Value" value="${esc(filterDlg.value || '')}">
  <div class="dlg-actions"><button type="submit">Apply</button> <button type="button" data-action="arc:close">Cancel</button></div>
</form>`, { title: name });
  }

{
    screens: {
      home: homeScreen,
      new: newWorkbookScreen,
      workbook: workbookScreen
    },
    screen(route) {
      const fn = this.screens[route.name] || this.screens.home;
      return fn.call(this, route);
    },
    afterRender() {
      const inp = document.querySelector('.cell-editor');
      if (pendingFocus && inp) {
        pendingFocus = false;
        try {
          inp.focus();
          inp.setSelectionRange(inp.value.length, inp.value.length);
        } catch (e) { /* ignore */ }
      }
    },
    actions: {
      /* ------------------------------------------------ workbook lifecycle */
      'new-blank-workbook'() { ARC.navigate('#/new'); },
      'create-workbook'({ form }) {
        const name = String(form.name || '').trim() || 'Untitled spreadsheet';
        const sheet = blankSheet('Sheet1');
        const wb = { id: ARC.uid('wb'), name, updatedAt: Date.now(), activeSheetId: sheet.id, sheets: [sheet] };
        wbList().unshift(wb);
        ARC.save();
        ARC.navigate('#/workbook/' + wb.id);
      },
      'open-rename-workbook'() {
        const wb = routeWb();
        if (!wb) return;
        renderRenameWorkbook(wb.name, null);
      },
      'save-workbook-name'({ form }) {
        const wb = routeWb();
        if (!wb) return;
        const name = String(form.name || '').trim();
        if (!name) { renderRenameWorkbook(String(form.name || ''), 'Workbook name cannot be empty'); return; }
        record(wb);
        wb.name = name;
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },
      'open-import'() { renderImport(null); },
      'confirm-import'({ form }) {
        const file = form && form.file;
        if (!file || !file.name) { renderImport('Invalid CSV file format. Import failed.'); return; }
        const reader = new FileReader();
        reader.onload = function () {
          let rows = null;
          try { rows = parseCSV(String(reader.result == null ? '' : reader.result)); } catch (e) { rows = null; }
          if (!rows) { renderImport('Invalid CSV file format. Import failed.'); return; }
          const name = String(file.name).replace(/\.csv$/i, '') || 'Imported CSV';
          const sheet = blankSheet('Sheet1');
          rows.forEach((row, r) => {
            row.forEach((value, c) => {
              if (r >= MAXR || c >= MAXC) return;
              if (value !== '') setRaw(sheet, r, c, value);
            });
          });
          const wb = { id: ARC.uid('wb'), name, updatedAt: Date.now(), activeSheetId: sheet.id, sheets: [sheet] };
          wbList().unshift(wb);
          ARC.save();
          ARC.closeDialog();
          ARC.navigate('#/workbook/' + wb.id);
        };
        reader.onerror = function () { renderImport('Invalid CSV file format. Import failed.'); };
        try { reader.readAsText(file, 'utf-8'); } catch (e) { renderImport('Invalid CSV file format. Import failed.'); }
      },
      'tb-export'() {
        // Never throw from a click handler: fall back to a data URL where object URLs are missing.
        try {
          const wb = routeWb();
          if (!wb) return;
          const sheet = activeSheet(wb);
          if (!sheet) return;
          let text = '';
          try { text = sheetToCSV(sheet); } catch (e) { text = ''; }
          const name = String(wb.name || 'workbook').replace(/[\\/:*?"<>|]/g, '_') + '.csv';
          let href = null;
          if (typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
            try { href = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' })); } catch (e) { href = null; }
          }
          if (!href) href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(text);
          const a = document.createElement('a');
          a.href = href;
          a.download = name;
          document.body.appendChild(a);
          a.click();
          a.remove();
          if (href.slice(0, 5) === 'blob:') setTimeout(() => { try { URL.revokeObjectURL(href); } catch (e) { /* ignore */ } }, 3000);
        } catch (e) { /* ignore */ }
      },

      /* ------------------------------------------------ worksheet lifecycle */
      'switch-sheet'({ id }) {
        const wb = routeWb();
        if (!wb) return;
        const target = wb.sheets.find((s) => s.id === id);
        if (!target) return;
        wb.activeSheetId = target.id;
        if (!target.sel) target.sel = { r1: 0, c1: 0, r2: 0, c2: 0 };
        touch(wb);
        ARC.save();
        ARC.render();
      },
      'add-sheet'() {
        const wb = routeWb();
        if (!wb) return;
        record(wb);
        const sheet = blankSheet(nextSheetName(wb, 'Sheet'));
        wb.sheets.push(sheet);
        wb.activeSheetId = sheet.id;
        touch(wb);
        ARC.save();
        ARC.render();
      },
      'open-sheet-menu'({ el, id }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = wb.sheets.find((s) => s.id === id);
        if (!sheet) return;
        const host = el.parentElement || el;
        ARC.openPopover(host, [
          { label: 'Rename', action: 'sheet-menu-rename' },
          { label: 'Delete', action: 'sheet-menu-delete' }
        ], { kind: 'menu', id: sheet.id, label: 'Worksheet options for ' + sheet.name });
      },
      'sheet-menu-rename'({ id }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = wb.sheets.find((s) => s.id === id);
        if (!sheet) return;
        renderRenameSheet(sheet, sheet.name, null);
      },
      'save-sheet-name'({ el, form }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = wb.sheets.find((s) => s.id === el.dataset.id);
        if (!sheet) return;
        const name = String(form.name || '').trim();
        if (!name) { renderRenameSheet(sheet, String(form.name || ''), 'Worksheet name cannot be empty'); return; }
        if (wb.sheets.some((s) => s.id !== sheet.id && s.name === name)) {
          renderRenameSheet(sheet, name, 'Worksheet name already exists');
          return;
        }
        record(wb);
        sheet.name = name;
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },
      'sheet-menu-delete'({ id }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = wb.sheets.find((s) => s.id === id);
        if (!sheet) return;
        if (wb.sheets.length <= 1) {
          ARC.notify('A workbook must contain at least one worksheet');
          return;
        }
        renderDeleteSheet(sheet);
      },
      'confirm-delete-sheet'({ id }) {
        const wb = routeWb();
        if (!wb) return;
        if (wb.sheets.some((s) => s.pivot && s.pivot.sourceId === id)) {
          ARC.closeDialog();
          ARC.notify('Please delete or rebuild dependent pivot tables first');
          ARC.render();
          return;
        }
        const idx = wb.sheets.findIndex((s) => s.id === id);
        if (idx < 0) { ARC.closeDialog(); return; }
        record(wb);
        wb.sheets.splice(idx, 1);
        if (wb.activeSheetId === id) {
          const next = wb.sheets[Math.max(0, idx - 1)] || wb.sheets[0];
          wb.activeSheetId = next.id;
        }
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },

