        const sheet = activeSheet(wb);
        const p = parseKey(id);
        if (!p) return;
        const rules = rulesForCell(sheet, p.r, p.c);
        if (!rules.length) return;
        const rule = rules[rules.length - 1];
        const html = (rule.values || []).map((v) =>
          `<button type="button" role="option" data-action="pick-dropdown-option" data-id="${esc(id)}" data-value="${esc(v)}">${esc(v)}</button>`
        ).join('');
        ARC.openPopover(el.parentElement || el, html, { label: 'Allowed values for ' + id });
      },
      'pick-dropdown-option'({ data }) {
        const wb = routeWb();
        if (!wb) return;
