      /* ------------------------------------------------ Data menu */
      'open-data-menu'({ el }) {
        ARC.openPopover(el.parentElement || el, [
          { label: 'Sort range', action: 'open-sort-dialog' },
          { label: 'Create filter', action: 'create-filter' },
          { label: 'Clear filter', action: 'clear-filter' },
          { label: 'Data validation', action: 'open-validation-dialog' },
          { label: 'Create pivot table', action: 'open-pivot-dialog' }
        ], { kind: 'menu', label: 'Data' });
      },

      /* ------------------------------------------------ sorting */
      'open-sort-dialog'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const s = Object.assign({}, sel(sheet));
        const eng = makeEngine(sheet);
        const cols = [];
        for (let c = s.c1; c <= s.c2; c++) {
          const text = eng.display(s.r1, c);
          cols.push({ value: text || colName(c), label: text || colName(c), index: c - s.c1 });
        }
        sortDlg = { rect: s, cols, by: cols.length ? cols[0].value : '' };
        renderSortDialog();
      },
      'apply-sort'({ form }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const rect = sortDlg ? sortDlg.rect : sel(sheet);
        let offset = 0;
        if (sortDlg) {
          const found = sortDlg.cols.find((x) => x.value === form.by);
          offset = found ? found.index : 0;
        }
        const asc = String(form.order || 'Ascending') !== 'Descending';
        const header = form.header === 'on' || form.header === true || form.header === 'true';
        record(wb);
        sortRange(sheet, rect, offset, asc, header);
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },

      /* ------------------------------------------------ filtering */
      'create-filter'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        let rect = Object.assign({}, sel(sheet));
        if (isSingle(rect)) {
          const used = usedRange(sheet);
          if (used) rect = Object.assign({}, used);
        }
        record(wb);
        setSheetFilters(sheet, [{ id: ARC.uid('flt'), range: rect, rules: {} }]);
