        ARC.save();
        ARC.render();
      },
      'clear-filter'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        if (!sheetFilters(sheet).length) return;
        record(wb);
        setSheetFilters(sheet, []);
        touch(wb);
        ARC.save();
        ARC.render();
      },
      'open-filter-dialog'({ data }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const filter = sheetFilters(sheet).find((f) => f.id === data.filter);
        if (!filter) return;
        const col = Number(data.id);
        const eng = makeEngine(sheet);
        const values = [];
        for (let r = filter.range.r1 + 1; r <= filter.range.r2; r++) {
          const v = eng.display(r, col);
          if (values.indexOf(v) < 0) values.push(v);
        }
        const current = filter.rules[col];
        filterDlg = {
          filterId: filter.id,
          col,
          values,
          checked: current && current.type === 'values' ? current.values.slice() : values.slice(),
          mode: 'values',
          op: current && current.type === 'condition' ? current.op : 'contains',
          value: current && current.type === 'condition' ? current.value : ''
        };
