      },
      'filter-clear-selection'() {
        if (!filterDlg) return;
        filterDlg.checked = [];
        renderFilterDialog();
      },
      'filter-apply-values'({ el }) {
        if (!filterDlg) return;
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const filter = sheetFilters(sheet).find((f) => f.id === filterDlg.filterId);
        if (!filter) { ARC.closeDialog(); return; }
        const formEl = (el && el.closest && el.closest('form')) || document.querySelector('#dialog-root form');
        const checked = formEl ? Array.prototype.slice.call(formEl.querySelectorAll('input[name="v"]:checked')).map((x) => x.value) : [];
        record(wb);
        filter.rules[filterDlg.col] = { type: 'values', values: checked };
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },
      'filter-apply-condition'({ form }) {
        if (!filterDlg) return;
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const filter = sheetFilters(sheet).find((f) => f.id === filterDlg.filterId);
        if (!filter) { ARC.closeDialog(); return; }
        const map = {
          'Text contains': 'contains',
          'Greater than': 'gt',
          'Before': 'before',
          'Is empty': 'empty',
          'Is not empty': 'notEmpty'
        };
        const op = map[form.condition] || 'contains';
        record(wb);
        filter.rules[filterDlg.col] = { type: 'condition', op, value: String(form.value == null ? '' : form.value) };
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },

      /* ------------------------------------------------ validation rules */
      'open-validation-dialog'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const s = sel(sheet);
        const existing = (sheet.validations || []).find((v) => rectEq(v.range, s));
        dvDraft = existing
          ? {
            type: existing.type === 'number' ? 'Number range' : 'Dropdown',
            allowed: existing.type === 'dropdown' ? (existing.values || []).join(', ') : '',
            min: existing.type === 'number' ? String(existing.min) : '',
            max: existing.type === 'number' ? String(existing.max) : '',
            existing: true
          }
          : { type: 'Dropdown', allowed: '', min: '', max: '', existing: false };
        renderValidationDialog();
      },
      'dv-type-change'({ value }) {
        if (!dvDraft) return;
        const formEl = document.querySelector('#dialog-root form');
        if (formEl) {
          const allowed = formEl.querySelector('input[name="allowed"]');
          const min = formEl.querySelector('input[name="min"]');
          const max = formEl.querySelector('input[name="max"]');
          if (allowed) dvDraft.allowed = allowed.value;
          if (min) dvDraft.min = min.value;
          if (max) dvDraft.max = max.value;
        }
        dvDraft.type = value;
        renderValidationDialog();
      },
      'save-validation'({ form }) {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const s = Object.assign({}, sel(sheet));
        const type = form.ruleType === 'Number range' ? 'number' : 'dropdown';
        record(wb);
        const rest = (sheet.validations || []).filter((v) => !rectEq(v.range, s));
        if (type === 'dropdown') {
          const values = String(form.allowed == null ? '' : form.allowed).split(',').map((x) => x.trim()).filter((x) => x !== '');
          rest.push({ id: ARC.uid('vr'), range: s, type: 'dropdown', values });
        } else {
          const min = parseFloat(form.min);
          const max = parseFloat(form.max);
          rest.push({
            id: ARC.uid('vr'),
            range: s,
            type: 'number',
            min: isNaN(min) ? 0 : min,
            max: isNaN(max) ? 0 : max
          });
        }
        sheet.validations = rest;
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },
      'delete-validation'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        const s = Object.assign({}, sel(sheet));
        record(wb);
        sheet.validations = (sheet.validations || []).filter((v) => !rectEq(v.range, s));
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },

      /* ------------------------------------------------ pivot tables */
      'open-pivot-dialog'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        let rect = Object.assign({}, sel(sheet));
        if (isSingle(rect)) {
          const used = usedRange(sheet);
          if (used) rect = Object.assign({}, used);
        }
        pivotSource = rect;
        renderPivotDialog();
      },
      'create-pivot'() {
        const wb = routeWb();
        if (!wb) return;
        const source = activeSheet(wb);
        const rect = pivotSource || sel(source);
        const name = nextSheetName(wb, 'Pivot');
        record(wb);
        const sheet = blankSheet(name);
        const eng = makeEngine(source);
        const headers = [];
        for (let c = rect.c1; c <= rect.c2; c++) headers.push(eng.display(rect.r1, c));
        sheet.pivot = {
          sourceId: source.id,
          range: Object.assign({}, rect),
          rows: headers[0] || '',
          columns: '',
          values: headers[1] || headers[0] || '',
          summarize: 'SUM'
        };
        wb.sheets.push(sheet);
        wb.activeSheetId = sheet.id;
        applyPivot(wb, sheet, true);
        touch(wb);
        ARC.save();
        ARC.closeDialog();
        ARC.render();
      },
      'pivot-apply'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        if (!sheet || !sheet.pivot) return;
        const root = document.querySelector('[aria-label="Pivot table editor"]') || document;
        const read = (n) => {
          const el = root.querySelector('select[name="' + n + '"]');
          return el ? el.value : '';
        };
        const cfg = {
          rows: read('rows'),
          columns: read('columns'),
          values: read('values'),
          summarize: read('summarize') || sheet.pivot.summarize
        };
        record(wb);
        const previous = Object.assign({}, sheet.pivot);
        sheet.pivot = Object.assign({}, previous, cfg);
        if (!applyPivot(wb, sheet, false)) {
          sheet.pivot = previous;
          ARC.render();
          return;
        }
        touch(wb);
        ARC.save();
        ARC.render();
      },
      'refresh-pivot'() {
        const wb = routeWb();
        if (!wb) return;
        const sheet = activeSheet(wb);
        if (!sheet || !sheet.pivot) return;
        record(wb);
        if (!applyPivot(wb, sheet, false)) {
          ARC.render();
          return;
        }
        touch(wb);
        ARC.save();
        ARC.render();
      }
    }
  }

function homeScreen() {
