      const m = /^(\$?)([A-Z]{1,3})(\$?)(\d+)$/.exec(tok.v);
      if (!m) return null;
      const node = { k: 'ref', c: colIndex(m[2]), r: parseInt(m[4], 10) - 1, absC: m[1] === '$', absR: m[3] === '$' };
      if (p.toks[p.i] && p.toks[p.i].t === ':') {
