      }
      return node;
    }
    return null;
  }

function displayOf(v) {
    if (!v) return '';
    if (v.kind === 'err') return v.err;
    if (v.kind === 'num') return fmtNum(v.num);
    if (v.kind === 'text') return v.text;
    return '';
  }

function colName(i) {
    let s = '';
    i += 1;
    while (i > 0) { const r = (i - 1) % 26; s = String.fromCharCode(65 + r) + s; i = Math.floor((i - 1) / 26); }
