function checkValue(sheet, r, c, raw) {
    const rules = rulesForCell(sheet, r, c);
    if (!rules.length) return { ok: true };
    const rule = rules[rules.length - 1];
    const text = String(raw == null ? '' : raw).trim();
    if (text === '') return { ok: true };
    if (rule.type === 'dropdown') {
      if ((rule.values || []).indexOf(text) >= 0) return { ok: true };
      return { ok: false, message: 'Please select one of the following values: ' + (rule.values || []).join(', ') };
