function deleteRow(sheet, at) {
    for (const k of Object.keys(sheet.cells || {})) {
      const p = parseKey(k);
      if (p && p.r === at) delete sheet.cells[k];
    }
    const moved = [];
    for (const k of Object.keys(sheet.cells || {})) {
      const p = parseKey(k);
      if (p && p.r > at) moved.push([k, p]);
    }
    moved.sort((a, b) => a[1].r - b[1].r);
    for (const pair of moved) {
      const v = sheet.cells[pair[0]];
      delete sheet.cells[pair[0]];
      sheet.cells[keyOf(pair[1].r - 1, pair[1].c)] = v;
    }
    // A reference into the deleted row cannot be preserved. It is marked here and resolved once the
    // whole expression is known: a trailing operand can be dropped together with its operator, while
    // anything else stays an explicit #REF! error in the stored formula and in the formula bar.
    rewriteFormulas(sheet, (ref) => (ref.r === at ? DROP : (ref.r > at ? { c: ref.c, r: ref.r - 1, absC: ref.absC, absR: ref.absR } : ref)));
    sheet.validations = (sheet.validations || []).map((v) => {
      const r = shiftRectDelete(v.range, 'row', at);
      return r ? Object.assign({}, v, { range: r }) : null;
    }).filter(Boolean);
    if (sheet.pivot) {
      const r = shiftRectDelete(sheet.pivot.range, 'row', at);
      if (r) sheet.pivot.range = r;
    }
    shiftDependentPivots(sheet, 'row', at, 0);
  }

function makeEngine(sheet) {
    const cells = sheet.cells || {};
    const cache = new Map();
    const visiting = new Set();

    function cellValue(key) {
      if (cache.has(key)) return cache.get(key);
      if (visiting.has(key)) return { kind: 'err', err: ERR.REF };
      visiting.add(key);
      const raw = Object.prototype.hasOwnProperty.call(cells, key) ? String(cells[key]) : '';
      let out;
      if (raw === '') out = { kind: 'empty' };
      else if (raw.charAt(0) === '=') out = runFormula(raw.slice(1));
      else if (isNumericText(raw)) out = { kind: 'num', num: parseFloat(raw.trim()) };
      else out = { kind: 'text', text: raw };
      visiting.delete(key);
      cache.set(key, out);
      return out;
    }
    function runFormula(src) {
      if (src.indexOf('#REF!') >= 0) return { kind: 'err', err: ERR.REF };
      const toks = tokenize(src);
      if (!toks) return { kind: 'err', err: ERR.GEN };
      const p = { toks, i: 0 };
      let node;
      try { node = parseExpr(p); } catch (e) { return { kind: 'err', err: ERR.GEN }; }
      if (!node || p.i !== toks.length) return { kind: 'err', err: ERR.GEN };
      const v = evalNode(node);
      if (v.kind === 'range') return { kind: 'err', err: ERR.GEN };
      return v;
    }
    function toNum(v) {
      if (!v) return { err: ERR.GEN };
      if (v.kind === 'err') return { err: v.err };
      if (v.kind === 'num') return { num: v.num };
      if (v.kind === 'empty') return { num: 0 };
      if (v.kind === 'text') {
        const t = v.text.trim();
        if (isNumericText(t)) return { num: parseFloat(t) };
        return { err: ERR.GEN };
      }
      return { err: ERR.GEN };
    }
    function evalNode(n) {
      if (n.k === 'num') return { kind: 'num', num: n.v };
      if (n.k === 'neg') {
        const v = toNum(evalNode(n.x));
        return v.err ? { kind: 'err', err: v.err } : { kind: 'num', num: -v.num };
      }
      if (n.k === 'ref') {
        if (n.r < 0 || n.c < 0) return { kind: 'err', err: ERR.REF };
        return cellValue(keyOf(n.r, n.c));
      }
      if (n.k === 'range') {
        const vals = [];
        for (let r = n.r1; r <= n.r2; r++) {
          for (let c = n.c1; c <= n.c2; c++) {
            if (r < 0 || c < 0) { vals.push({ kind: 'err', err: ERR.REF }); continue; }
            vals.push(cellValue(keyOf(r, c)));
          }
        }
        return { kind: 'range', vals };
      }
      if (n.k === 'bin') {
        const a = toNum(evalNode(n.l));
        if (a.err) return { kind: 'err', err: a.err };
        const b = toNum(evalNode(n.r));
        if (b.err) return { kind: 'err', err: b.err };
        let v;
        if (n.op === '+') v = a.num + b.num;
        else if (n.op === '-') v = a.num - b.num;
        else if (n.op === '*') v = a.num * b.num;
        else { if (b.num === 0) return { kind: 'err', err: ERR.DIV }; v = a.num / b.num; }
        return { kind: 'num', num: v };
      }
      if (n.k === 'call') {
        const vals = [];
        for (const a of n.args) {
          const v = evalNode(a);
          if (v.kind === 'range') { for (const x of v.vals) vals.push(x); } else vals.push(v);
        }
        const nums = vals.filter((x) => x.kind === 'num').map((x) => x.num);
        const sum = nums.reduce((s, x) => s + x, 0);
        if (n.name === 'SUM') return { kind: 'num', num: sum };
        if (n.name === 'COUNT') return { kind: 'num', num: nums.length };
        if (n.name === 'AVERAGE') return nums.length ? { kind: 'num', num: sum / nums.length } : { kind: 'err', err: ERR.DIV };
        if (n.name === 'MIN') return { kind: 'num', num: nums.length ? Math.min.apply(null, nums) : 0 };
        if (n.name === 'MAX') return { kind: 'num', num: nums.length ? Math.max.apply(null, nums) : 0 };
        return { kind: 'err', err: ERR.NAME };
      }
      return { kind: 'err', err: ERR.GEN };
    }
    return {
      value: cellValue,
      display(r, c) { return displayOf(cellValue(keyOf(r, c))); },
      raw(r, c) {
        const k = keyOf(r, c);
        return Object.prototype.hasOwnProperty.call(cells, k) ? String(cells[k]) : '';
      }
    };
  }

function tokenize(src) {
    const toks = [];
    let i = 0;
    while (i < src.length) {
      const ch = src[i];
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue; }
