        continue;
      }
      if (/[A-Za-z_$]/.test(ch)) {
        const m = /^\$?[A-Za-z_][A-Za-z0-9_$]*/.exec(src.slice(i));
        toks.push({ t: 'name', v: m[0].toUpperCase() });
        i += m[0].length;
        continue;
      }
      if ('+-*/():,'.indexOf(ch) >= 0) { toks.push({ t: ch }); i++; continue; }
      return null;
    }
    return toks;
  }

