    let left = parseTerm(p);
    if (!left) return null;
    while (p.i < p.toks.length && (p.toks[p.i].t === '+' || p.toks[p.i].t === '-')) {
      const op = p.toks[p.i++].t;
      const right = parseTerm(p);
      if (!right) return null;
      left = { k: 'bin', op, l: left, r: right };
    }
    return left;
  }

function parseTerm(p) {
    let left = parseUnary(p);
    if (!left) return null;
    while (p.i < p.toks.length && (p.toks[p.i].t === '*' || p.toks[p.i].t === '/')) {
      const op = p.toks[p.i++].t;
      const right = parseUnary(p);
      if (!right) return null;
      left = { k: 'bin', op, l: left, r: right };
    }
    return left;
  }

function parseUnary(p) {
    if (p.i < p.toks.length && p.toks[p.i].t === '-') { p.i++; const x = parseUnary(p); return x ? { k: 'neg', x } : null; }
    if (p.i < p.toks.length && p.toks[p.i].t === '+') { p.i++; return parseUnary(p); }
    return parsePrimary(p);
  }

function parsePrimary(p) {
    const tok = p.toks[p.i];
    if (!tok) return null;
    if (tok.t === 'num') { p.i++; return { k: 'num', v: tok.v }; }
    if (tok.t === '(') {
      p.i++;
      const e = parseExpr(p);
      if (!e) return null;
      if (!p.toks[p.i] || p.toks[p.i].t !== ')') return null;
      p.i++;
      return e;
    }
    if (tok.t === 'name') {
      p.i++;
      if (p.toks[p.i] && p.toks[p.i].t === '(') {
        p.i++;
        const args = [];
        if (p.toks[p.i] && p.toks[p.i].t === ')') { p.i++; }
        else {
          for (;;) {
            const a = parseExpr(p);
            if (!a) return null;
            args.push(a);
            if (p.toks[p.i] && p.toks[p.i].t === ',') { p.i++; continue; }
            if (p.toks[p.i] && p.toks[p.i].t === ')') { p.i++; break; }
