      if (!m) return null;
      const node = { k: 'ref', c: colIndex(m[2]), r: parseInt(m[4], 10) - 1, absC: m[1] === '$', absR: m[3] === '$' };
      if (p.toks[p.i] && p.toks[p.i].t === ':') {
        p.i++;
        const t2 = p.toks[p.i];
        if (!t2 || t2.t !== 'name') return null;
        const m2 = /^(\$?)([A-Z]{1,3})(\$?)(\d+)$/.exec(t2.v);
        if (!m2) return null;
        p.i++;
        const r2 = parseInt(m2[4], 10) - 1;
        const c2 = colIndex(m2[2]);
        return {
          k: 'range',
          r1: Math.min(node.r, r2), r2: Math.max(node.r, r2),
          c1: Math.min(node.c, c2), c2: Math.max(node.c, c2)
        };
      }
      return node;
    }
    return null;
  }

function colName(i) {
    let s = '';
    i += 1;
    while (i > 0) { const r = (i - 1) % 26; s = String.fromCharCode(65 + r) + s; i = Math.floor((i - 1) / 26); }
